import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Contador } from './solution.mjs';

test('todo contador começa em zero', () => {
  const contador = new Contador();
  assert.equal(contador.valor, 0);
});

test('incrementar soma 1 e devolve o novo valor', () => {
  const contador = new Contador();
  assert.equal(contador.incrementar(), 1);
  assert.equal(contador.incrementar(), 2);
  assert.equal(contador.valor, 2);
});

test('zerar devolve 0 e zera o valor', () => {
  const contador = new Contador();
  contador.incrementar();
  contador.incrementar();
  assert.equal(contador.zerar(), 0);
  assert.equal(contador.valor, 0);
});

test('cada contador guarda o seu próprio valor', () => {
  const primeiro = new Contador();
  const segundo = new Contador();
  primeiro.incrementar();
  primeiro.incrementar();
  assert.equal(primeiro.valor, 2);
  assert.equal(segundo.valor, 0);
});

solutionCode:
// O contador guarda o valor e sabe modificar a si mesmo pelos métodos.
export class Contador {
  constructor() {
    this.valor = 0; // todo contador nasce em zero
  }

  incrementar() {
    this.valor += 1; // this é o próprio contador sendo usado
    return this.valor; // devolve o novo valor para quem chamou
  }

  zerar() {
    this.valor = 0;
    return this.valor;
  }
}
